import { ParentComponent } from "solid-js";

import { ComponentRegistry } from "#core/ui-next/services/component-registry.js";

export interface PanelFrameComponentProps {
	class?: string;
}

const ModalFrameComponent: ParentComponent<PanelFrameComponentProps> = (props) => {
	return (
		<div
			class={`img-modal-frame relative px-20 py-6 flex flex-col items-center pointer-events-auto ${props.class ?? ""}`}
		>
			{props.children}
		</div>
	);
};

export const ModalFrame = ComponentRegistry.register({
	name: "PopupFrameComponent",
	createInstance: ModalFrameComponent,
});
